def retry(func):
    def wrapper(*args, **kwargs):
        max_retries = 3
        for _ in range(max_retries):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                print(f"Retrying due to exception: {e}")
                if!max_retries:
                    raise
        # If all retries fail, raise the last exception
        raise
    return wrapper

